import fs from 'node:fs';

const THEME = { NAVY: '#040D6D', BLUE: '#58ABFF', OFFW: '#F4F4F4', GREEN: '#1BBF85', RED: '#FF3B4E' };

const page = fs.readFileSync('client/src/pages/trades/trades-terminal.tsx', 'utf8');
const m = page.match(/export const TP_TERM_CSS = `([\s\S]*?)`;/);
if (!m) throw new Error('TP_TERM_CSS not found');
let raw = m[1];
for (const [k, v] of Object.entries(THEME)) raw = raw.split('${' + k + '}').join(v);
if (raw.includes('${')) console.log('!! unresolved interpolation:', raw.match(/\$\{[^}]+\}/g));

const scoped = fs.readFileSync('client/src/features/terminal/trades/trades-terminal-view.css', 'utf8');

// Parse a flat stylesheet (no nesting) into [selector, body] pairs, keeping @keyframes whole.
function parse(css) {
  const out = [];
  let i = 0;
  while (i < css.length) {
    const brace = css.indexOf('{', i);
    if (brace === -1) break;
    let sel = css.slice(i, brace).trim();
    // depth-aware close
    let depth = 1, j = brace + 1;
    while (j < css.length && depth > 0) {
      if (css[j] === '{') depth++;
      else if (css[j] === '}') depth--;
      j++;
    }
    const body = css.slice(brace + 1, j - 1);
    sel = sel.replace(/\/\*[\s\S]*?\*\//g, '').trim();
    if (sel) out.push([sel, body]);
    i = j;
  }
  return out;
}

const norm = (body) =>
  body
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .split(';')
    .map((d) => d.trim().replace(/\s+/g, ' '))
    .filter(Boolean)
    .sort()
    .join('; ');

const unscope = (sel) =>
  sel
    .split(',')
    .map((s) =>
      s
        .trim()
        .replace(/\.trades-terminal-view\.tp-viewport/g, '.tp-viewport')
        .replace(/\.trades-terminal-view\s+/g, '')
    )
    .join(', ');

const A = parse(raw).filter(([s]) => !s.startsWith('@import'));
const B = parse(scoped);

const bmap = new Map();
for (const [sel, body] of B) bmap.set(unscope(sel), norm(body));

const missing = [], differing = [], identical = [];
for (const [sel, body] of A) {
  const key = sel.split(',').map((s) => s.trim()).join(', ');
  if (!bmap.has(key)) missing.push(key);
  else if (bmap.get(key) !== norm(body)) differing.push([key, norm(body), bmap.get(key)]);
  else identical.push(key);
}
const amap = new Set(A.map(([s]) => s.split(',').map((x) => x.trim()).join(', ')));
const extra = [...bmap.keys()].filter((k) => !amap.has(k));

console.log(`page rules: ${A.length}   scoped rules: ${B.length}`);
console.log(`\nIDENTICAL after constant substitution: ${identical.length}`);
console.log(`\nMISSING from the scoped file (${missing.length}):`);
missing.forEach((s) => console.log('  - ' + s));
console.log(`\nDIFFERING (${differing.length}):`);
for (const [sel, a, b] of differing) {
  console.log('  · ' + sel);
  const ad = a.split('; '), bd = b.split('; ');
  const onlyA = ad.filter((d) => !bd.includes(d));
  const onlyB = bd.filter((d) => !ad.includes(d));
  onlyA.forEach((d) => console.log('      page only : ' + d));
  onlyB.forEach((d) => console.log('      scoped only: ' + d));
}
console.log(`\nONLY in the scoped file (${extra.length}):`);
extra.forEach((s) => console.log('  + ' + s));

