    const el = document.querySelector(".tp-subbar-ind");
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.x, w: r.width };
  });
  if (!after) return null;
  return { dx: round(Math.abs(after.x - before.x)), dw: round(Math.abs(after.w - before.w)) };
