/* CSSOM truth: which rules define .tp-send-slot / .tp-subbar on each vertical,
   and which stylesheet owns them. */
import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, VERTICALS, newMobilePage } from "/home/runner/workspace/scripts/mobile-fixtures.mjs";

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH, args: ["--no-sandbox"] });
for (const v of ["retail", "property", "trades"]) {
  const { context, page } = await newMobilePage(browser, v, { width: 390, height: 844 });
  try {
    await page.goto(`${BASE_URL}${VERTICALS[v].route}`, { waitUntil: "domcontentloaded", timeout: 30_000 });
    await page.waitForSelector(".tp-viewport", { timeout: 15_000 });
    await page.waitForTimeout(1200);
    const r = await page.evaluate(() => {
      const hits = [];
      const sheets = [...document.styleSheets];
      sheets.forEach((sh, i) => {
        let rules;
        try { rules = sh.cssRules; } catch { return; }
        for (const rule of rules) {
          const sel = rule.selectorText;
          if (!sel) continue;
          if (/tp-send-slot|tp-subbar\b/.test(sel)) {
            hits.push({ i, owner: sh.ownerNode?.tagName + (sh.ownerNode?.id ? "#" + sh.ownerNode.id : "") + (sh.href ? " " + sh.href.split("/").pop() : ""), sel: sel.slice(0, 90) });
          }
        }
      });
      const el = document.querySelector(".tp-send-slot");
      const matched = el ? [...document.styleSheets].flatMap((sh) => { try { return [...sh.cssRules]; } catch { return []; } })
        .filter((rl) => rl.selectorText && /tp-send-slot/.test(rl.selectorText))
        .map((rl) => ({ sel: rl.selectorText, css: rl.style.cssText.slice(0, 120), matches: el.matches(rl.selectorText.split(",")[0].trim()) || null })) : [];
      return { totalSheets: sheets.length, sendSlotRules: matched, subbarSelectors: hits.filter((h) => /tp-subbar\b/.test(h.sel)).map((h) => h.sel) };
    });
    console.log("\n=== " + v + "  (sheets: " + r.totalSheets + ")");
    console.log("  .tp-send-slot rules:");
    r.sendSlotRules.forEach((x) => console.log("    " + x.sel + "  ->  " + x.css));
    console.log("  .tp-subbar selectors (" + r.subbarSelectors.length + "):");
    [...new Set(r.subbarSelectors)].forEach((s) => console.log("    " + s));
  } catch (e) {
    console.log(v, "ERROR", e.message.split("\n")[0]);
  } finally {
    await context.close();
  }
}
await browser.close();

