// Three-way rule comparison: retail TP_CSS vs property TP_TERM_CSS vs the
// scoped trades feature CSS. How much is genuinely shared?
import fs from 'node:fs';

const R = '/home/runner/workspace/';
function extract(file, name) {
  const src = fs.readFileSync(R + file, 'utf8');
  const re = new RegExp('(?:export )?const ' + name + ' = `([\\s\\S]*?)`;');
  const m = src.match(re);
  if (!m) throw new Error(name + ' not in ' + file);
  return m[1];
}
function parse(css) {
  const out = [];
  let i = 0;
  while (i < css.length) {
    const brace = css.indexOf('{', i);
    if (brace === -1) break;
    let sel = css.slice(i, brace);
    let depth = 1, j = brace + 1;
    while (j < css.length && depth > 0) {
      if (css[j] === '{') depth++;
      else if (css[j] === '}') depth--;
      j++;
    }
    sel = sel.replace(/\/\*[\s\S]*?\*\//g, '').replace(/@import[^;]+;/g, '').trim();
    if (sel) out.push([sel.split(',').map((s) => s.trim()).join(', '), css.slice(brace + 1, j - 1)]);
    i = j;
  }
  return out;
}
const norm = (b) => b.replace(/\/\*[\s\S]*?\*\//g, '').split(';').map((d) => d.trim().replace(/\s+/g, ' ')).filter(Boolean).sort().join('; ');
const normKf = (b) => b.replace(/\s+/g, ' ').trim();

const retail = parse(extract('client/src/features/terminal/retail/RetailTerminalViewCore.jsx', 'TP_CSS'));
const property = parse(extract('client/src/features/terminal/property/PropertyTerminalView.tsx', 'TP_TERM_CSS'));
const trades = parse(fs.readFileSync(R + 'client/src/features/terminal/trades/trades-terminal-view.css', 'utf8'))
  .map(([s, b]) => [s.split(',').map((x) => x.trim().replace(/\.trades-terminal-view\.tp-viewport/, '.tp-viewport').replace(/\.trades-terminal-view\s+/, '')).join(', '), b]);

const sets = { retail, property, trades };
const all = new Map(); // sel -> {vertical: normbody}
for (const [v, rules] of Object.entries(sets)) {
  for (const [sel, body] of rules) {
    if (!all.has(sel)) all.set(sel, {});
    all.get(sel)[v] = sel.startsWith('@keyframes') ? normKf(body) : norm(body);
  }
}

const sharedAll = [], sharedSome = [], diverge = [], only = { retail: [], property: [], trades: [] };
for (const [sel, byV] of all) {
  const vs = Object.keys(byV);
  const vals = [...new Set(Object.values(byV))];
  if (vs.length === 1) only[vs[0]].push(sel);
  else if (vals.length === 1 && vs.length === 3) sharedAll.push(sel);
  else if (vals.length === 1) sharedSome.push([sel, vs.join('+')]);
  else diverge.push([sel, byV]);
}

console.log(`rules: retail ${retail.length}  property ${property.length}  trades ${trades.length}   union ${all.size}`);
console.log(`\nIDENTICAL in all three (${sharedAll.length})`);
console.log(`IDENTICAL in two (${sharedSome.length}): ` + sharedSome.map(([s, v]) => `${s} [${v}]`).join(', '));
console.log(`\nDIVERGING (${diverge.length}):`);
for (const [sel, byV] of diverge) {
  const keys = Object.keys(byV);
  console.log('  · ' + sel + '   present in: ' + keys.join(', '));
  const decls = {};
  for (const v of keys) for (const d of byV[v].split('; ')) (decls[d] ??= []).push(v);
  for (const [d, vs] of Object.entries(decls)) if (vs.length < keys.length) console.log(`      ${vs.join('+').padEnd(24)} ${d}`);
}
for (const v of Object.keys(only)) console.log(`\nONLY ${v} (${only[v].length}): ` + only[v].join(', '));

