/* Phase 2 scoper. Reads a `<style>` template literal, emits a real .css file with
   every selector scoped under the vertical's root class, and lifts @keyframes out
   (they cannot be scoped by a descendant selector — they go in the shared file).
   Line-oriented on purpose: comments, grouping and formatting survive verbatim,
   so the diff is reviewable by eye. */
import fs from 'node:fs';

const R = '/home/runner/workspace/';

export function scope(css, root, { dropKeyframes = true } = {}) {
  const lines = css.split('\n');
  const out = [];
  const keyframes = [];
  let depth = 0;
  let inKf = false;
  let kfBuf = [];

  for (const line of lines) {
    const opens = (line.match(/\{/g) || []).length;
    const closes = (line.match(/\}/g) || []).length;

    if (inKf) {
      kfBuf.push(line);
      depth += opens - closes;
      if (depth === 0) { keyframes.push(kfBuf.join('\n')); kfBuf = []; inKf = false; }
      continue;
    }

    if (depth === 0 && /^\s*@keyframes\b/.test(line)) {
      depth += opens - closes;
      if (depth === 0) keyframes.push(line);
      else { inKf = true; kfBuf = [line]; }
      continue;
    }

    if (depth === 0 && line.includes('{')) {
      const cut = line.indexOf('{');
      const sel = line.slice(0, cut);
      const rest = line.slice(cut);
      const scoped = sel
        .split(',')
        .map((s) => {
          const t = s.trim();
          if (!t) return s;
          const lead = s.slice(0, s.length - s.trimStart().length);
          // `.tp-viewport` is the root element itself, not a descendant of it.
          if (t.startsWith('.tp-viewport')) return lead + root + t;
          return lead + root + ' ' + t;
        })
        .join(',');
      out.push(scoped + rest);
      depth += opens - closes;
      continue;
    }

    out.push(line);
    depth += opens - closes;
  }

  return { css: out.join('\n'), keyframes };
}

export function literal(file, name) {
  const src = fs.readFileSync(R + file, 'utf8');
  const m = src.match(new RegExp('(?:export )?const ' + name + ' = `([\\s\\S]*?)`;'));
  if (!m) throw new Error(name + ' not found in ' + file);
  return m[1];
}

/* ── self-check: scoping must not change any rule's declarations ─────────── */
function parse(css) {
  const out = [];
  let i = 0;
  while (i < css.length) {
    const brace = css.indexOf('{', i);
    if (brace === -1) break;
    let sel = css.slice(i, brace);
    let depth = 1, j = brace + 1;
    while (j < css.length && depth > 0) {
      if (css[j] === '{') depth++;
      else if (css[j] === '}') depth--;
      j++;
    }
    sel = sel.replace(/\/\*[\s\S]*?\*\//g, '').trim();
    if (sel) out.push([sel.split(',').map((s) => s.trim()).join(', '), css.slice(brace + 1, j - 1)]);
    i = j;
  }
  return out;
}
const norm = (b) => b.replace(/\/\*[\s\S]*?\*\//g, '').split(';').map((d) => d.trim().replace(/\s+/g, ' ')).filter(Boolean).sort().join('; ');

export function check(before, after, root, label) {
  const A = parse(before).filter(([s]) => !s.startsWith('@keyframes'));
  const B = parse(after);
  const strip = (s) => s.split(',').map((x) => x.trim().replace(new RegExp('^' + root.replace('.', '\\.') + '(\\.tp-viewport)'), '$1').replace(new RegExp('^' + root.replace('.', '\\.') + '\\s+'), '')).join(', ');
  const problems = [];
  if (A.length !== B.length) problems.push(`rule count ${A.length} -> ${B.length}`);
  for (let i = 0; i < Math.min(A.length, B.length); i++) {
    if (strip(B[i][0]) !== A[i][0]) problems.push(`#${i} selector: "${A[i][0]}" -> "${B[i][0]}"`);
    if (norm(B[i][1]) !== norm(A[i][1])) problems.push(`#${i} body changed on ${A[i][0]}`);
    if (!B[i][0].split(',').every((s) => s.trim().startsWith(root))) problems.push(`#${i} unscoped: ${B[i][0]}`);
  }
  console.log(`${label}: ${A.length} rules scoped under ${root} — ${problems.length ? 'PROBLEMS' : 'clean'}`);
  problems.slice(0, 20).forEach((p) => console.log('   ! ' + p));
  return problems.length === 0;
}

