import fs from 'node:fs';
import { scope, literal, check } from './scope.mjs';

const R = '/home/runner/workspace/';
const HEAD = (vertical, root, src) =>
`/* ${vertical} terminal chrome — scoped under \`${root}\`.
   Was an unscoped \`<style>\` template literal in ${src} (RC-6): three copies of
   this sheet defined the same \`.tp-*\` rules globally with different values, so
   whichever <style> tag was later in the DOM won. Scoping is phase 2 of
   docs/PLAN-2026-08-17-mobile-responsive-ui.md §5.1.

   Shared @keyframes live in ../terminal-keyframes.css — a descendant selector
   cannot scope a keyframe, so deduping them is the only way to stop them
   colliding. */
@import "../terminal-keyframes.css";
`;

const jobs = [
  {
    vertical: 'Retail',
    root: '.retail-terminal-view',
    src: 'features/terminal/retail/RetailTerminalViewCore.jsx',
    file: 'client/src/features/terminal/retail/RetailTerminalViewCore.jsx',
    name: 'TP_CSS',
    out: 'client/src/features/terminal/retail/retail-terminal-view.css',
  },
  {
    vertical: 'Property',
    root: '.property-terminal-view',
    src: 'features/terminal/property/PropertyTerminalView.tsx',
    file: 'client/src/features/terminal/property/PropertyTerminalView.tsx',
    name: 'TP_TERM_CSS',
    out: 'client/src/features/terminal/property/property-terminal-view.css',
  },
];

const allKeyframes = new Map();
let ok = true;
for (const j of jobs) {
  const raw = literal(j.file, j.name);
  const { css, keyframes } = scope(raw, j.root);
  ok = check(raw, css, j.root, j.vertical) && ok;
  for (const kf of keyframes) {
    const name = kf.match(/@keyframes\s+([\w-]+)/)[1];
    const prev = allKeyframes.get(name);
    const norm = (s) => s.replace(/\s+/g, ' ').trim();
    if (prev && norm(prev) !== norm(kf)) console.log(`  !! @keyframes ${name} differs between verticals`);
    if (!prev) allKeyframes.set(name, kf);
  }
  fs.writeFileSync(R + j.out, HEAD(j.vertical, j.root, j.src) + css.replace(/^\n+/, '\n'));
  console.log(`   wrote ${j.out}`);
}
console.log('\nkeyframes collected: ' + [...allKeyframes.keys()].join(', '));
fs.writeFileSync('/tmp/claude-1000/-home-runner-workspace/5cad547c-0397-4d65-a0e8-65f3ceef9f18/scratchpad/keyframes.txt', [...allKeyframes.values()].join('\n'));
process.exit(ok ? 0 : 1);

