78	        const unitPriceCents = Math.round(Number(line.unitPrice) * 100);
79	        return { description: line.description.trim(), qty, unitPriceCents, lineTotalCents: Math.round(qty * unitPriceCents) };
80	      });
81	      if (!clientId) throw new Error('Choose a client');
82	      if (lineItems.some(line => !line.description || !Number.isInteger(line.qty) || line.qty <= 0 || line.unitPriceCents < 0)) throw new Error('Complete every line item');
83	      const validUntil = new Date(); validUntil.setDate(validUntil.getDate() + 30);
84	      const selected = clients.find((client: any) => client.id === clientId);
85	      const body = {
86	        clientProfileId: clientId,
87	        lineItems,
88	        deliveryChannel: selected?.preferredChannel || 'email',
89	        depositEnabled,
90	        depositType: depositEnabled ? depositType : undefined,
91	        depositValue: depositEnabled ? (depositType === 'percent' ? Math.round(Number(depositValue)) : Math.round(Number(depositValue) * 100)) : undefined,
92	        validUntil: validUntil.toISOString(),
93	        notes: notes.trim() || undefined,
94	      };
95	      const response = await fetch('/api/trades/quotes', { method: 'POST', headers: { 'Content-Type': 'application/json', ...tradesHeaders() }, body: JSON.stringify(body) });
96	      if (!response.ok) {
97	        notifyIfBillingCardRequired(response);
98	        throw new Error(await response.json().then((d: any) => d.message).catch(() => 'Could not create quote'));
99	      }
100	      return response.json();
101	    },
102	    onSuccess: quote => { queryClient.invalidateQueries({ queryKey: ['/api/trades/quotes'] }); setCreated(quote); },
103	    onError: (err: any) => setError(err?.message || 'Could not create quote'),
104	  });
105	
106	  const updateLine = (id: number, field: keyof QuoteDraftLine, value: string) => setLines(cur => cur.map(l => l.id === id ? { ...l, [field]: value } : l));
107	  const gstReg = !!auth?.user?.gstRegistered;
108	
109	  const publicUrl = created ? `${window.location.origin}/trades/quote/${created.token}` : '';
110	  const downloadPdf = async () => {
111	    if (!created?.id) return;
112	    const response = await fetch(`/api/trades/quotes/${created.id}/pdf`, { headers: tradesHeaders() });
113	    if (!response.ok) { setError(await response.json().then((d: any) => d.message).catch(() => 'Could not download PDF')); return; }
114	    const blob = await response.blob();
115	    const url = URL.createObjectURL(blob);
116	    const link = document.createElement('a');
117	    link.href = url; link.download = `quote-${String(created.token || created.id).slice(0, 8)}.pdf`; link.click();
118	    URL.revokeObjectURL(url);
119	  };
120	
121	  return (
122	    <QuoteView
123	      clients={clients}
124	      clientId={clientId}
125	      lines={lines}
126	      depositEnabled={depositEnabled}
127	      depositType={depositType}
128	      depositValue={depositValue}
129	      notes={notes}
130	      created={created}
131	      error={error}
132	      gstRegistered={gstReg}
133	      gstMode={gstMode}
134	      totals={totals}
135	      publicUrl={publicUrl}
136	      isCreating={createQuote.isPending}
137	      onClientIdChange={setClientId}
138	      onLineChange={updateLine}
139	      onRemoveLine={(id) => setLines(current => current.filter(line => line.id !== id))}
140	      onAddLine={() => setLines(current => [...current, { id: Date.now(), description: '', qty: '1', unitPrice: '' }])}
141	      onDepositEnabledChange={setDepositEnabled}
142	      onDepositTypeChange={setDepositType}
143	      onDepositValueChange={setDepositValue}
144	      onNotesChange={setNotes}
145	      onCreate={() => createQuote.mutate()}
146	      onCopyLink={() => { void navigator.clipboard?.writeText(publicUrl); }}
147	      onDownloadPdf={downloadPdf}
148	      onCancel={onCancel}
149	      onExit={onExit}
150	    />
151	  );
152	}
