/* Phase 2 verification: are all `.tp-*` rules scoped, is every keyframe defined
   once, and does `.tp-send-slot.show` resolve on all three verticals? */
import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, VERTICALS, newMobilePage } from "/home/runner/workspace/scripts/mobile-fixtures.mjs";

const ROOTS = { retail: ".retail-terminal-view", property: ".property-terminal-view", trades: ".trades-terminal-view" };
const browser = await chromium.launch({ executablePath: CHROMIUM_PATH, args: ["--no-sandbox"] });
let bad = 0;
for (const [v, route] of [["retail", "/terminal"], ["property", "/property/terminal"], ["trades", "/trades/terminal"], ["trades-quote", "/trades/quote"]]) {
  const vert = v === "trades-quote" ? "trades" : v;
  const { context, page } = await newMobilePage(browser, vert, { width: 390, height: 844 });
  try {
    await page.goto(`${BASE_URL}${route}`, { waitUntil: "domcontentloaded", timeout: 30_000 });
    await page.waitForSelector(".tp-viewport", { timeout: 15_000 });
    await page.waitForTimeout(1200);
    const r = await page.evaluate(() => {
      const rules = [...document.styleSheets].flatMap((sh) => { try { return [...sh.cssRules]; } catch { return []; } });
      const unscoped = rules
        .filter((rl) => rl.selectorText && /(^|[\s,>+~])\.tp-/.test(rl.selectorText))
        .map((rl) => rl.selectorText)
        .filter((s) => s.split(",").some((p) => /^\s*\.tp-/.test(p)));
      const kf = {};
      for (const rl of rules) if (rl.type === CSSRule.KEYFRAMES_RULE) kf[rl.name] = (kf[rl.name] ?? 0) + 1;
      const sendSlotShow = rules.filter((rl) => rl.selectorText && /\.tp-send-slot\.show/.test(rl.selectorText)).map((rl) => rl.selectorText);
      const root = document.querySelector(".tp-viewport");
      const box = root?.getBoundingClientRect();
      const bar = document.querySelector(".tp-subbar")?.getBoundingClientRect();
      return {
        unscopedTpRules: [...new Set(unscoped)],
        dupKeyframes: Object.entries(kf).filter(([, n]) => n > 1),
        keyframeCount: Object.keys(kf).length,
        sendSlotShow,
        rootClass: root?.className,
        viewport: box && { w: Math.round(box.width), h: Math.round(box.height) },
        subbar: bar && { w: Math.round(bar.width), h: Math.round(bar.height) },
        screens: document.querySelectorAll(".tp-screen").length,
      };
    });
    const fail = r.unscopedTpRules.length || r.dupKeyframes.length || !r.sendSlotShow.length;
    if (fail) bad++;
    console.log(`\n=== ${v}  ${fail ? "FAIL" : "ok"}`);
    console.log("  root            " + r.rootClass);
    console.log("  viewport/subbar " + JSON.stringify(r.viewport) + " / " + JSON.stringify(r.subbar) + "  .tp-screen x" + r.screens);
    console.log("  unscoped .tp-*  " + (r.unscopedTpRules.length ? r.unscopedTpRules.join(" | ") : "none"));
    console.log("  keyframes       " + r.keyframeCount + " unique, duplicates: " + (r.dupKeyframes.length ? JSON.stringify(r.dupKeyframes) : "none"));
    console.log("  send-slot.show  " + (r.sendSlotShow.join(" | ") || "MISSING"));
  } catch (e) {
    bad++;
    console.log(v, "ERROR", e.message.split("\n")[0]);
  } finally {
    await context.close();
  }
}
await browser.close();
console.log("\n" + (bad ? bad + " route(s) failing" : "all routes clean"));
process.exit(bad ? 1 : 0);

