1	#!/usr/bin/env node
2	/* The phone geometry gate — docs/PLAN-2026-08-17-mobile-responsive-ui.md §7.2.
3	 *
4	 * WHY THIS EXISTS. Every probe in scripts/desktop-shots/ runs at >=1194px, and
5	 * `verify-mobile-retail-regression.mjs` runs one viewport and asserts only the
6	 * outer box, so it passes against the broken UI (§3 RC-7). The primary root
7	 * cause is a `@media (max-width: 640px)` rule, which means the entire class of
8	 * defect this plan is about is invisible to every gate the repo had.
9	 *
10	 * WHAT IT DOES. Measures — never looks — across 3 verticals x 6 viewports, and
11	 * compares every number against a recorded baseline (§7.6: "no worse than
12	 * baseline", never a permanently red command). Metrics split two ways:
13	 *
14	 *   COUNTERS   things that should trend to zero: horizontal overflow, elements
15	 *              crossing the viewport edge, clipped text, controls the 44px rule
16	 *              has inflated, `.tp-*` stylesheet collisions, indicator drift.
17	 *              The gate fails if any counter is HIGHER than baseline.
18	 *   RATCHETS   things that should trend up or hold: visibleStackRows. The gate
19	 *              fails if any ratchet is LOWER than baseline.
20	 *   RECORDED   component boxes and the §6.1/§3.1 token values. Reported as a
21	 *              diff so a phase can see what it moved; never fails on its own,
22	 *              because "different" is the point of every phase after this one.
23	 *
24	 * A run that is BETTER than baseline prints what improved and tells you to
25	 * re-record. That is the ratchet: each phase tightens the file it is measured
26	 * against.
27	 *
28	 * WHAT IT DELIBERATELY DOES NOT GATE ON. Page/console errors. The dev server
29	 * serves a Replit banner from a third-party origin that is ORB-blocked, so a
30	 * gate keyed on console output can never exit 0 here — see
31	 * `probe-transitions.mjs`, which has that bug. Errors are collected and printed
32	 * under `--verbose`, never scored.
33	 *
34	 * Usage: dev server on :5000, single instance (see the dev-server memory note).
35	 *   node scripts/verify-mobile-responsive.mjs             compare, exit 1 on regression
36	 *   node scripts/verify-mobile-responsive.mjs --update    re-record the baseline
37	 *   node scripts/verify-mobile-responsive.mjs --json      print the full measurement
38	 *   node scripts/verify-mobile-responsive.mjs --verbose   include page errors
39	 */
40	import { readFileSync, writeFileSync, existsSync } from "node:fs";
41	import { fileURLToPath } from "node:url";
42	import { dirname, join } from "node:path";
43	import { chromium } from "playwright";
44	import { BASE_URL, CHROMIUM_PATH, VERTICALS, newMobilePage } from "./mobile-fixtures.mjs";
45	
46	const HERE = dirname(fileURLToPath(import.meta.url));
47	const BASELINE = join(HERE, "verify-mobile-responsive.baseline.json");
48	
49	const argv = new Set(process.argv.slice(2));
50	const UPDATE = argv.has("--update");
51	const AS_JSON = argv.has("--json");
52	const VERBOSE = argv.has("--verbose");
53	
54	/* §4.1's device matrix. 390x844 is the reference the design is calibrated to;
55	   320x568 is where the vertical budget gets thin (§4.3). */
56	const VIEWPORTS = [
57	  { width: 320, height: 568 },
58	  { width: 360, height: 640 },
59	  { width: 375, height: 667 },
60	  { width: 390, height: 844 },
61	  { width: 412, height: 915 },
62	  { width: 430, height: 932 },
63	];
64	
65	/* The reference viewport also runs with simulated insets (§7.2 clause 8). */
66	const REFERENCE = "390x844";
67	const SAFE_AREA = { top: 59, bottom: 34, left: 0, right: 0 };
68	
69	/* §3.1's token set. All null until phase 6 — recording them now is what makes
70	   the v1 defect (a token that silently computed to 0px) impossible to reland
71	   unnoticed: the value is in the baseline from the first phase that writes it. */
72	const TOKENS = [
73	  "--u", "--sp-1", "--sp-2", "--sp-3", "--sp-4", "--sp-6", "--sp-7",
74	  "--bar-h", "--btn-h", "--row-h", "--stack-hdr-h", "--kp-size", "--fab-size",
