84	/* ─────────────────────────────────────────────────────────────────────────
85	   The in-page measurement. One evaluate() per cell: crossing the bridge is
86	   the expensive part, and a partial measurement is worse than none.
87	   ───────────────────────────────────────────────────────────────────────── */
88	async function measure(page, allowlist) {
89	  return page.evaluate((ALLOW) => {
90	    const r1 = (n) => Math.round(n * 10) / 10;
