1	import { readdirSync, readFileSync } from "fs";
2	import { join } from "path";
3	
4	/* The §7.4 static guard for RC-6 of docs/PLAN-2026-08-17-mobile-responsive-ui.md.
5	 *
6	 * The phone terminal shipped the same `.tp-*` stylesheet four times — three of
7	 * them unscoped `<style>` template literals inside components — so which sheet
8	 * won depended on which terminal happened to be mounted last. Measured on
9	 * /property/terminal, two <style> tags defined `.tp-subbar` at once and the
10	 * action bar rendered at 241x48 instead of its authored 316x56.
11	 *
12	 * Phase 2 moved all three into real, scoped `.css` files and deleted the
13	 * fourth. This guard is what stops the next one appearing. A grep over
14	 * `**\/*.css` cannot see it — most of this app's CSS lives in template literals
15	 * and inline style objects, which is exactly how the problem got in.
16	 */
17	
18	const SRC = join(__dirname, "..");
19	
20	const VERTICAL_SHEETS = [
21	  { css: "features/terminal/retail/retail-terminal-view.css", root: ".retail-terminal-view" },
22	  { css: "features/terminal/property/property-terminal-view.css", root: ".property-terminal-view" },
23	  { css: "features/terminal/trades/trades-terminal-view.css", root: ".trades-terminal-view" },
24	];
25	
26	const SHARED_KEYFRAMES = "features/terminal/terminal-keyframes.css";
27	const SHARED_TOKENS = "features/terminal/terminal-tokens.css";
28	
29	/* Every host that mounts a .tp-viewport must import the shared token layer —
30	 * a vertical that doesn't fails silently into var() fallbacks, the same
31	 * failure shape as RC-6 and the reason this guard exists at all.
32	 * SPEC-2026-08-20-dock-implementation.md §9.B1. */
33	const TOKEN_IMPORTERS = [
34	  "features/terminal/retail/RetailTerminalView.tsx",
35	  "features/terminal/property/PropertyTerminalView.tsx",
36	  "features/terminal/trades/TradesTerminalView.tsx",
37	  "pages/trades/quote-builder.tsx",
38	];
39	
40	function walk(dir: string, test: RegExp): string[] {
41	  const out: string[] = [];
42	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
43	    const full = join(dir, entry.name);
44	    if (entry.isDirectory()) {
45	      if (entry.name === "node_modules") continue;
46	      out.push(...walk(full, test));
47	    } else if (test.test(entry.name)) {
48	      out.push(full);
49	    }
50	  }
51	  return out;
52	}
53	
54	/** Selector text of every rule in a flat stylesheet, `@keyframes` excluded. */
55	function selectorsOf(css: string): string[] {
56	  const out: string[] = [];
57	  let depth = 0;
58	  let inKeyframes = false;
59	
60	  for (const line of css.split("\n")) {
61	    const opens = (line.match(/\{/g) ?? []).length;
62	    const closes = (line.match(/\}/g) ?? []).length;
63	
64	    if (depth === 0 && /^\s*@keyframes\b/.test(line)) inKeyframes = opens > closes;
65	    else if (depth === 0 && line.includes("{") && !inKeyframes) {
66	      const selector = line.slice(0, line.indexOf("{")).replace(/\/\*.*?\*\//g, "").trim();
67	      if (selector) out.push(...selector.split(",").map((part) => part.trim()).filter(Boolean));
68	    }
69	
70	    depth += opens - closes;
71	    if (depth === 0) inKeyframes = false;
72	  }
73	  return out;
74	}
75	
76	describe("terminal CSS scoping (RC-6)", () => {
77	  it("declares no `.tp-` rule outside a vertical root in any vertical stylesheet", () => {
78	    const unscoped: string[] = [];
79	
80	    for (const sheet of VERTICAL_SHEETS) {
81	      const css = readFileSync(join(SRC, sheet.css), "utf8");
82	      for (const selector of selectorsOf(css)) {
83	        if (!selector.startsWith(sheet.root)) unscoped.push(`${sheet.css}: ${selector}`);
84	      }
85	    }
86	
87	    expect(unscoped).toEqual([]);
88	  });
89	
90	  it("ships no `<style>` template literal that declares a bare `.tp-` selector", () => {
91	    const offenders: string[] = [];
92	
93	    for (const file of walk(SRC, /\.(?:tsx|jsx|ts|js)$/)) {
94	      if (file.includes("__tests__")) continue;
95	      const source = readFileSync(file, "utf8");
96	      if (!/<style[\s>]/.test(source)) continue;
97	
98	      // Anything that reaches a <style> tag is a candidate: the literal is
99	      // usually a module constant referenced by name, not written inline.
100	      for (const literal of source.match(/`[^`]*`/g) ?? []) {
101	        if (!/\.tp-/.test(literal)) continue;
102	        for (const selector of selectorsOf(literal.slice(1, -1))) {
103	          if (/^\.tp-/.test(selector)) {
104	            offenders.push(`${file.slice(SRC.length + 1)}: ${selector}`);
105	          }
106	        }
107	      }
108	    }
109	
110	    expect(offenders).toEqual([]);
111	  });
112	
113	  it("defines each shared keyframe exactly once, in the shared sheet", () => {
114	    const shared = readFileSync(join(SRC, SHARED_KEYFRAMES), "utf8");
115	    const names = (shared.match(/@keyframes\s+([\w-]+)/g) ?? []).map((k) => k.split(/\s+/)[1]);
116	
117	    expect(names.length).toBeGreaterThan(0);
118	    expect(new Set(names).size).toBe(names.length);
119	
120	    // A descendant selector cannot scope a keyframe — the name is global and the
121	    // last definition parsed wins — so a second copy anywhere is a live
122	    // collision that scoping does not fix.
123	    const duplicates: string[] = [];
124	    for (const file of walk(SRC, /\.(?:css|tsx|jsx|ts|js)$/)) {
125	      if (file.endsWith(SHARED_KEYFRAMES) || file.includes("__tests__")) continue;
126	      for (const found of readFileSync(file, "utf8").match(/@keyframes\s+(tp-[\w-]+)/g) ?? []) {
127	        duplicates.push(`${file.slice(SRC.length + 1)}: ${found}`);
128	      }
129	    }
130	
131	    expect(duplicates).toEqual([]);
132	  });
133	
134	  it("imports the shared token layer from every .tp-viewport host", () => {
135	    const missing: string[] = [];
136	
137	    for (const file of TOKEN_IMPORTERS) {
138	      const source = readFileSync(join(SRC, file), "utf8");
139	      if (!/terminal-tokens\.css/.test(source)) missing.push(file);
140	    }
141	
142	    expect(missing).toEqual([]);
143	  });
144	});

